def somme(lignes, sens, champ):
    return sum(l[champ] or 0.0 for l in lignes if l['sens'] == sens)
def totaux():
    d_po = somme(L, 'rec', 'delta'); d_dep = somme(L, 'dep', 'delta')
    cur_po = somme(L, 'rec', 'cur')
    restes = {}
    for fn, tot in COFOG.items():
        connu = sum(l['cur'] or 0.0 for l in L if l['sens'] == 'dep' and l['fn'] == fn)
        restes[fn] = tot - connu
    return dict(d_po=d_po, d_dep=d_dep, cur_po=cur_po, restes=restes)
