V6_NET_V56 = M['v6_pensions_2060'] + M['v6_recettes_2060'] - M['v6_substitution_2060'] - M['v6_plancher_2060']   # v5.6 : ouverture de l'âge libre en 3 ans (pour mémoire)
SOLDE_V58 = SOLDE_APRES; SOLDE_V57 = M['solde_v55'] + EFFET_V57   # v5.8 = bilan poste par poste ; v5.7 recalculée, pour mémoire
SOLDE_A = SOLDE_APRES - EFFET_V58              # v5.5 = v5.4 (v5.3 + 345 €) + holdings 2 %, trusts, SCI (sans abattement), SANS le dispositif V6, la fiscalité d'orientation, le fioul, la gratuité, le CIR réorienté ni la détention
SOLDE_B = SOLDE_A + K_B
def taux_pour(cible_solde, grille=None):
    """Taux plat (fraction) auquel le solde central atteint cible_solde, interpolation linéaire entre points voisins de la grille (GRILLE_V55 par défaut ; GRILLE_V54 pour la v5.4 et la v5.3)."""
    pts = sorted((grille or GRILLE_V55).items())
    for (t0, s0), (t1, s1) in zip(pts, pts[1:]):
        if s0 <= cible_solde <= s1: return t0 + (t1 - t0) * (cible_solde - s0) / (s1 - s0)
    raise ValueError('hors grille')
def solde_a_taux(t):
    pts = sorted(GRILLE_V55.items())
    for (t0, s0), (t1, s1) in zip(pts, pts[1:]):
        if t0 <= t <= t1: return s0 + (s1 - s0) * (t - t0) / (t1 - t0)
    raise ValueError('hors grille')
TAUX_A = taux_pour(0.0)
TAUX_B = taux_pour(-K_B)
TAUX_V54 = taux_pour(0.0, GRILLE_V54)
TAUX_V53 = taux_pour(-M['cout_345'], GRILLE_V54)   # à 340 € : le solde de la v5.4 est inférieur de 0,19 à celui de la v5.3 : l'équilibre v5.3 est atteint quand le solde v5.4 vaut −0,19
TAUX_V58_CROISIERE = M['te_v58_croisiere']; TAUX_V58_CREUX = M['te_v58_creux']   # v5.8, exportés du modèle (bisection)
TAUX_V57_CROISIERE = M['te_v57_croisiere']; TAUX_V57_CREUX = M['te_v57_creux']        # v5.7, exportés du modèle (bisection)
TAUX_V56_CROISIERE = M['te_v56_croisiere']                 # v5.6 : taux d'équilibre quand le dispositif V6 est à son niveau de 2060 (central), exporté du modèle (bisection) ; contrôlé sur la grille (tests)
TAUX_V56_CREUX = M['te_v56_creux']                         # taux d'équilibre de l'année la plus coûteuse (2029), exporté du modèle
def taux_annee(y):
    return [x for x in TRAJ_V58 if x[0] == y][0][10]                      # exporté du modèle (bisection au 0,0001 point)
def taux_grille(y):
    r = [x for x in TRAJ_V58 if x[0] == y][0]
    return taux_pour(-r[8], GRILLE_V56)                                  # recalcul indépendant par interpolation de la grille (contrôle)
POINT = 10.3962   # Md€ par point de taux autour de 42 % (rapport_decisions_0511c.js : solde à 43 % moins solde à 42 %)

def fmt(x, n=1):
    if x is None: return '—'
    s = ('%.' + str(n) + 'f') % x
    return s.replace('.', ',').replace('-', '−')
def sg(x, n=1):
    if x is None: return '—'
    return ('+' if x > 0.0005 else '') + fmt(x, n)
def pct(x): return fmt(100 * x / PIB, 1) + ' %'

def cible(l): return None if l['cur'] is None else l['cur'] + l['delta']

