def table_lignes(lignes, avec_fn=False):
    out = ['| N° | Poste | Avant (Md€) | Cible (Md€) | Écart | Statut | Dans le taux v5.3 | Preuve | Source (avant et cible) ; note |', '|---|---|---|---|---|---|---|---|---|']
    for l in lignes:
        out.append('| %s | %s | %s | %s | %s | %s | %s | %s | %s |' % (l['id'], l['poste'], fmt(l['cur']), fmt(cible(l)), sg(l['delta']), l['statut'], l['compte'], l['preuve'], l['source'] + (' ; ' + l['note'] if l['note'] else '')))
    return '\n'.join(out)

def md():
    p = []
    for bloc in dict.fromkeys(l['bloc'] for l in L):
        lignes = [l for l in L if l['bloc'] == bloc]
        p.append('### ' + bloc + '\n')
        p.append(table_lignes(lignes))
        if bloc == B1:
            p.append('| | **Sous-total prélèvements obligatoires** | **%s** | **%s** | **%s** | | | | |' % (fmt(PO_AVANT), fmt(PO_APRES), sg(T['d_po'])))
        else:
            p.append('| | **Écart du bloc (dépenses)** | | | **%s** | | | | |' % sg(sum(l['delta'] for l in lignes)))
        p.append('')
    p.append('### Restes non modélisés, inchangés (pour que les totaux tombent sur l\'APU consolidé 2024)\n')
    p.append('| Fonction (COFOG 2024) | Total de la fonction | Dont lignes modélisées ci-dessus (avant) | **Reste inchangé** |'); p.append('|---|---|---|---|')
