PU_43, PU_42, TAXE_1PC_NETTE, TAXE_1PC_IMMO = 897.8018, 887.1594, 86.4171, 77.8124   # exportés de decisions_0511i.js (prelevementUnique, taxe1pc)
BASCULE_EFFET_SOLDE = 0.0      # transfert entre l'État et les collectivités : nul sur le solde consolidé (les suppressions sont déjà dans P06, P07, N08 ; la TVA reste en P11)
SOLDE_V59 = SOLDE_APRES + BASCULE_EFFET_SOLDE
