def bascule_parts(pu=PU_43):
    out = {}
    for k, n in BASCULE.items():
        tot = n['tf'] + n['cfe'] + n['dmto'] + n['tva'] + n['vm']; du_pu = tot - n['tf']
        out[k] = {'total': tot, 'part_1pc': n['tf'] / TAXE_1PC_NETTE, 'part_1pc_immo': n['tf'] / TAXE_1PC_IMMO, 'part_pu': du_pu / pu, 'points': 100 * (0.43 if pu == PU_43 else 0.42) * du_pu / pu}
    return out
def md_bascule():
    rows = ['| Niveau | Perçu en 2024 (Md€) | dont taxe foncière | Part de la taxe de 1 % (produit net) | Part du prélèvement unique en 2029 (43 %) | en points des 43 |', '|---|---|---|---|---|---|']
    P = bascule_parts()
    for k in ('bloc', 'departements', 'regions', 'aom'):
        x = P[k]; rows.append('| %s | %s | %s | %s | %s %% | %s |' % (BASCULE[k]['libelle'], fmt(x['total'], 2), fmt(BASCULE[k]['tf'], 2), (fmt(100 * x['part_1pc'], 1) + ' %') if x['part_1pc'] else '—', fmt(100 * x['part_pu'], 2), fmt(x['points'], 2)))
    tot = sum(P[k]['total'] for k in P); tpu = sum(P[k]['part_pu'] for k in P)
    rows.append('| **Total** | **%s** | %s | | **%s %%** | **%s** |' % (fmt(tot, 2), fmt(BASCULE['bloc']['tf'], 2), fmt(100 * tpu, 2), fmt(sum(P[k]['points'] for k in P), 2)))
    rows.append('| **Effet sur le solde consolidé** | | | | **%s** | |' % fmt(BASCULE_EFFET_SOLDE, 2))
    return '\n'.join(rows)

