def tests_base():
    proche(EFFET_BASE, _SB['totaux']['central'], 1e-9, 'base : effet du bilan = total du module JS')
    proche(_SB['dette']['effet'], EFFET_BASE, 1e-9, 'base : la dette de l\'export utilise le même effet que le bilan')
    proche(SOLDE_BASE, SOLDE_V74_CORR + EFFET_BASE, 1e-12, 'base : solde = v7.4 B corrigée + effet')
    proche(V74['corrige']['effet'], EFFET_CORR, 1e-9, 'base posée sur la même couche corrigée')
    proche(sum(l['v'][1] for l in L_BASE if l['sens'] == 'po') - sum(l['v'][1] for l in L_BASE if l['sens'] == 'dep') * 0 - (PO_BASE - PO_V74_CORR), 0.0, 1e-9, 'base : prélèvements = lignes « po »')
    proche((PO_BASE - PO_V74_CORR) - (DEP_BASE - DEP_V74_CORR), EFFET_BASE, 1e-9, 'base : effet = Δ prélèvements − Δ dépenses')
    assert len(L_BASE) == 14 and [l['id'] for l in L_BASE] == ['BT%02d' % k for k in range(1, 15)], 'base : lignes BT01-BT14'
    assert EFFET_BASE_SC[0] > EFFET_BASE > EFFET_BASE_SC[2], 'base : favorable > central > défavorable'
    proche([l for l in L_BASE if l['id'] == 'BT01'][0]['v'][1], _SB['v75']['recette'] - _c4['recetteTaxe'], 1e-9, 'BT01 = recette v7.5 − G05')
    proche([l for l in L_BASE if l['id'] == 'BT12'][0]['v'][1], -2.334, 1e-9, 'BT12 = C24 (formation, variante B), qui sort des trous « à vérifier »')
    assert MANQUE_BASE['reference'] > V74['corrige']['combinaison']['manque']['reference'], 'base : le manque de référence augmente'
    for (k, lib, rv, pa, ec, dt) in JEUX:
        if k in ('a', 'c'): proche(dt['reference'], 0.0, 0.05, 'jeu (%s) : dette stable en macro de référence' % k)
        proche(rv + pa + ec, MANQUE_BASE['reference'] if k != 'b' else _SB['jeuB']['delta'], 0.02, 'jeu (%s) : total = manque comblé' % k)
    assert _SB['jeuB']['reste'] > 0.75 * MANQUE_BASE['reference'], 'jeu (b) : la fonction du patrimoine seule laisse plus des trois quarts du manque'
    assert max(g_['delta'] for g_ in _SB['grilleB']) == _SB['jeuB']['delta'], 'jeu (b) : meilleur point de la grille'
    cto = {c_['id']: c_ for c_ in _SB['casTypesBase']}
    proche(cto['cadre_20000']['ecartH453'], -10.5, 0.1, 'anomalie reproduite (coût H453) : −10 €/mois')
    proche(cto['cadre_20000']['ecartOF'], -98.0, 0.1, 'anomalie corrigée (super-brut OpenFisca) : −98 €/mois')
    assert _SB['marginalActuel']['m10_20'] > 0.65, 'non-monotonie restante réelle : marginal actuel > 65 % entre 10 000 et 20 000 € brut'
    proche(PO_ELARGIS_AVANT / PIB, 0.442, 0.001, 'PO élargis aujourd\'hui ≈ 44,2 % (milieu de 43,8-44,6 %)')
    return True

