    for l in L_TRANS: rows.append('| %s | %s | %s / **%s** / %s | %s | %s |' % (l['id'], l['poste'], sg(l['v'][0], 2), sg(l['v'][1], 2), sg(l['v'][2], 2), l['cote'], l['note']))
    rows.append('| | **Effet de la couche (jeu JR)** | %s / **%s** / %s | | manque de la base : %s |' % (sg(EFFET_TRANS_SC[0], 2), sg(EFFET_TRANS, 2), sg(EFFET_TRANS_SC[2], 2), fmt(MANQUE_BASE['reference'], 1)))
