    for l in L_EF: rows.append('| %s | %s | %s / **%s** / %s | %s | %s |' % (l['id'], l['poste'], sg(l['v'][0], 3), sg(l['v'][1], 3), sg(l['v'][2], 3), l['cote'], l['note']))
