def md_scenarios():
    S1, S2, S3 = _SCN['S1'], _SCN['S2'], _SCN['S3']
    rows = ['| Scénario | Leviers ajoutés à la base (Md€/an) | a | PO officiels ; élargis | Dette / PIB 2038 ; 2058 | Cadre 10 000 € brut (€/mois) |', '|---|---|---|---|---|---|']
    cas = {c['id']: c for c in _SCN['cas']}; tj = _SCN['traj']; i38, i58 = 2038 - 2029, 2058 - 2029
    def f1(x): return fmt(100 * x, 1) + ' %'
    def ligne(nom, lev, a, p, key, j):
        rows.append('| %s | %s | %s | %s ; %s | %s ; %s | %s |' % (nom, lev, fmt(a, 4), f1(p['pct']), f1(p['elargisPct']), f1(tj[key][i38]), f1(tj[key][i58]), sg(cas['cadre_10000']['v'][j], 0)))
    ligne('S1 réforme neutre (aucun levier ; marge %s)' % fmt(S1['marge'], 1), '0', S1['a'], S1['po'], 'S1', 0)
    ligne('S1 au plus juste (marge rendue par la fonction des revenus)', sg(-S1['marge'], 2), S1['aPlus'], S1['poPlus'], 'S1p', 1)
    ligne('S2 dette stable (jeu JRR)', sg(S2['effet'], 2), S2['a'], S2['po'], 'S2', 2)
    ligne('S3 neutre à la bascule, stable dès 2038 (rampe 2029-2038)', sg(S3['F'], 2), S3['a'], S3['po'], 'S3', 3)
    rows.append('| Droit actuel (déficit de 2024 conservé) | — | — | 42,7 %% ; 44,2 %% | %s ; %s | 0 |' % (f1(tj['actuel'][i38]), f1(tj['actuel'][i58])))
    return '\n'.join(rows)
