    rows.append('| CS00b | D18, euros : L1 + L2 %s, base CAF lue %s, plafond des départs %s = **%s** (gestion supprimée du modèle %s) : la ligne S10 « écart de lecture » devient « base CAF lue et plafond des départs » | 0 | appliquée (présentation) | V18701, V18801 |' % (fmt(D18_EUROS['l1_l2'], 2), sg(D18_EUROS['base_caf'], 2), sg(D18_EUROS['plafond_departs'], 2), fmt(sum(D18_EUROS.values()), 2), fmt(M['gestion_nette'] + 0.05 + 0.64, 4)))
