def tests_conso():
    proche(D18_ETP['avant'] - D18_ETP['douane_retires'], D18_ETP['concernes'], 0, 'V18700 : 49 000 − 1 400 = 47 600 ETP concernés')
    assert D18_ETP['absorbables'] < D18_ETP['concernes'], 'V18701 : les ETP absorbables restent sous les ETP concernés'
    proche(D18_ETP['absorbables'] / D18_ETP['concernes'], CONSO0611['plafond'], 0.03, 'V18701 : part absorbable des ETP ≈ part des euros gardés par le plafond (0,817)')
    proche(sum(D18_EUROS.values()), M['gestion_nette'] + 0.05 + 0.64, 0.01, 'V18701 : 4,90 − 0,25 − 0,85 = gestion supprimée de D18 (3,7986)')
    proche(CONSO0611['urssaf']['part'], 0.35 * 1.85, 1e-9, 'V18702 : Urssaf à 35 % de 1,85')
    proche(EFFET_CONSO, (0.35 * 1.85 - 0.46) * CONSO0611['plafond'], 1e-9, 'CS01 = (0,6475 − 0,46) × facteur du plafond')
    assert 'N10' not in [c['id'] for c in L_CAND], 'N10 n\'est pas additionné à CS01'
    proche(EFFET_CAND, CONSO0611['candidats'][1], 1e-9, 'candidats du bilan = candidats du module JS')
    proche(EFFET_CAND + EFFET_CONSO, 0.7, 0.1, 'candidats + CS01 ≈ 0,7 Md€ (inventaire § 6)')
    assert EFFET_CAND_SC[0] >= EFFET_CAND >= EFFET_CAND_SC[2] > 0, 'candidats : favorable >= central >= défavorable > 0'
    r = _RC['M1m'][1]
    assert r['d23'] <= 0.69 * _LV['M1m'][I2040] + 1e-9 and r['d18'] <= 1.24 * CONSO0611['plafond'] + 1e-9, 'recouvrements bornés par les deux lignes qui se chevauchent'
    proche(RECOUVREMENT, r['d23'] + r['d18'] + r['m3'], 1e-9, 'recouvrement = somme des trois parts')
    assert 4.5 < RECOUVREMENT < 5.25, 'recouvrement corrigé entre 4,5 et 5,25 Md€ (5,25 annoncé : part DGFiP surestimée)'
    proche(CUMUL_NET, CUMUL_BRUT - RECOUVREMENT, 1e-9, 'cumul net = brut − recouvrement')
    assert MANQUE_CONSO['reference'] > MANQUE_BASE['reference'] - EFFET_CONSO, 'le recouvrement rouvre le manque de la base'
    proche(MANQUE_CONSO['reference'] - MANQUE_CONSO_CAND['reference'], EFFET_CAND, 1e-6, 'les candidats baissent le manque de leur montant')
    proche(SCN_C['S1']['marge'] - _SCN['S1']['marge'], EFFET_CONSO, 0.01, 'S1 : seule CS01 change la marge (aucun levier, donc aucun recouvrement)')
    assert SCN_C['S3']['F'] > _SCN['S3']['F'] and SCN_C['S3']['picAn'] <= 2038, 'S3 : il faut plus de leviers, pic de la dette au plus tard en 2038'
    assert max(SCN_C['S2']['traj'][:30]) <= SCN_C['S2']['r0'] + 1e-6, 'S2 consolidé : dette stable sur 30 ans en macro de référence'
    proche(SOLDE_BASE_CONSO - SOLDE_BASE, EFFET_CONSO, 1e-12, 'couche de consolidation posée sur la base sans la modifier')
    return True

def proche(a, b, tol, msg):
    assert abs(a - b) <= tol, '%s : obtenu %.4f, attendu %.4f ± %g' % (msg, a, b, tol)

