def md_gtc():
    rows = ['| N° | Poste | Écart au solde : réactions faibles / **centrales** / fortes (Md€) | Cote | Note |', '|---|---|---|---|---|']
    for l in L_GTC: rows.append('| ' + ' | '.join([l['id'], l['poste'], sg(l['v'][0], 2) + ' / **' + sg(l['v'][1], 2) + '** / ' + sg(l['v'][2], 2), l['cote'], l['note']]) + ' |')
    rows.append('| | **Effet de la variante « coût constant »** | ' + sg(EFFET_GTC_SC[0], 2) + ' / **' + sg(EFFET_GTC, 2) + '** / ' + sg(EFFET_GTC_SC[2], 2) + ' | | solde de croisière ' + sg(SOLDE_BASE_CONSO + EFFET_GTC, 2) + ' |')
    rows.append('| | Total versé chômage + pont + maladie (sans comportement) | ' + fmt(VERSE_GTC, 2) + ' Md€ | | aujourd\'hui ' + fmt(_CC['aujourdhui'], 1) + ' (' + sg(VERSE_GTC - _CC['aujourdhui'], 2) + ') ; base ' + fmt(_CC['base'], 2) + ' (' + sg(VERSE_GTC - _CC['base'], 2) + ') |')
    rows.append('| | Courbe généreuse (λ = −3) : garantie versée ' + fmt(_CC['genereuse']['garantie'], 2) + ', comportement ' + sg(_CC['genereuse']['recettes'], 2) + ' | | | |')
    return '\n'.join(rows)
def md_gt():
    rows = ['| N° | Poste | Écart au solde : favorable / **central** / défavorable (Md€) | Cote | Note |', '|---|---|---|---|---|']
    for l in L_GT: rows.append('| ' + ' | '.join([l['id'], l['poste'], sg(l['v'][0], 2) + ' / **' + sg(l['v'][1], 2) + '** / ' + sg(l['v'][2], 2), l['cote'], l['note']]) + ' |')
    rows.append('| | **Effet de la couche** | ' + sg(EFFET_GT_SC[0], 2) + ' / **' + sg(EFFET_GT, 2) + '** / ' + sg(EFFET_GT_SC[2], 2) + ' | | dont garantie seule (GT01-GT03) ' + sg(sum(l['v'][1] for l in L_GT[:3]), 2) + ' |')
    rows.append('| | **Solde de croisière (base consolidée + couche)** | **' + sg(SOLDE_BASE_GT, 2) + '** | | sans la couche : ' + sg(SOLDE_BASE_CONSO, 2) + ' |')
    for c in GT0711['troisModele']:
        rows.append('| | Variante « coût du modèle » : ' + fmt(100 * c['p0'], 0) + ' %, ' + str(c['T']) + ' mois, λ = ' + fmt(c['lam'], 2) + ' | supplément ' + fmt(c['sup'], 2) + ' ; comportement ' + sg(c['rec'], 2) + ' | | GT01-GT03 = 0 par construction |')
    return '\n'.join(rows)
def tests_gt():
    assert [l['id'] for l in L_GT] == ['GT01', 'GT02', 'GT03', 'GT04', 'GT06', 'GT05'], 'couche garantie : lignes GT01-GT06'
    proche(GT0711['pont']['surcout'][1], 1.0, 1e-3, 'pont vers la retraite : surcoût central calibré à 1 Md€')
    proche(GT0711['supplement'][1] + GT0711['demissionnaires'][1] + GT0711['independants'][1], GT0711['budgetAC'], 1e-4, 'garantie : supplément total = coût de l\'assurance chômage actuelle (37,1)')
    proche(GT0711['budgetAC'], [l for l in L if l['id'] == 'D02'][0]['cur'], 1e-9, 'budget de la garantie = coût actuel de la ligne D02')
    proche(GT0711['budgetModele'], M['chomage_nouveau'], 1e-9, 'référence = complément de D02 dans la base (12,56)')
    proche(sum(l['v'][1] for l in L_GT[:3]), M['chomage_nouveau'] - GT0711['budgetAC'], 1e-4, 'GT01-GT03 = 12,56 − 37,1 (à coût égal à l\'AC, la base perd la réduction de D02)')
    assert EFFET_GT_SC[0] >= EFFET_GT >= EFFET_GT_SC[2], 'couche garantie : favorable >= central >= défavorable'
    proche(SOLDE_BASE_GT - SOLDE_BASE_CONSO, EFFET_GT, 1e-12, 'couche garantie : posée sur la base consolidée sans la modifier')
    assert all(abs(c['sup'] - GT0711['budgetModele']) < 1e-3 for c in GT0711['troisModele']), 'variantes « coût du modèle » : supplément = 12,56'
    assert [l['id'] for l in L_GTC] == ['GTC1', 'GTC2', 'GTC3', 'GTC4'], 'variante coût constant : lignes GTC1-GTC4'
    proche(_CC['aujourdhui'], 49.2, 1e-9, 'coût actuel de référence : AC 37,1 + IJ 12,1 = 49,2')
    assert VERSE_GTC < _CC['aujourdhui'] and VERSE_GTC - _CC['recettes'][1] - _CC['pontRecettes'][1] < _CC['aujourdhui'], 'coût constant : pas plus cher qu\'aujourd\'hui (versé et avec comportement)'
    proche(_CC['pont'][1], 1.0, 1e-3, 'coût constant : pont calibré à 1 Md€')
    assert abs(_CC['maladie'][1] - 12.1) < 0.5, 'arrêts maladie : coût proche des IJ actuelles (taux plein 64 %)'
    proche(SOLDE_BASE_CONSO + EFFET_GTC - SOLDE_BASE_CONSO, EFFET_GTC, 1e-12, 'variante posée sur la base consolidée')
    return True

