def md_d7_lignes():
    rows = ['| N° | Poste | Écart au solde : favorable / **central** / défavorable (Md€) | Cote |', '|---|---|---|---|']
    for l in L_D7['gtc_droite']:
        if l['id'].startswith('DG'): continue
