    for v in VARS_D7:
        for l in L_D7[v]:
            if l['id'].startswith('DG'): rows.append('| ' + ' | '.join([l['id'] + ' (' + v + ')', l['poste'], sg(l['v'][0], 2) + ' / **' + sg(l['v'][1], 2) + '** / ' + sg(l['v'][2], 2), l['cote']]) + ' |')
    for v in VARS_D7:
        rows.append('| | **Effet de la couche, garantie (' + v + ')** | ' + sg(EFFET_D7_SC[v][0], 2) + ' / **' + sg(EFFET_D7[v], 2) + '** / ' + sg(EFFET_D7_SC[v][2], 2) + ' | solde de croisière ' + sg(SOLDE_D7[v], 2) + ' |')
