    rows = ['| Ménage (revenu net santé, €/mois) | Aujourd\'hui | **coût constant (défaut)** | (a) 12,56 Md€ | (b) 25 Md€ | (c) 37,1 Md€ |', '|---|---|---|---|---|---|']
