L_D8 = _D8['lignes']
EFFET_D8_NOUV = [sum(l['v'][k] for l in L_D8) for k in range(3)]
EFFET_D8 = _D8['S3']['effetCouche']
def md_d8_lignes():
    rows = ['| N° | Poste | Écart au solde : favorable / **central** / défavorable (Md€) | Cote |', '|---|---|---|---|']
    for l in L_D8: rows.append('| ' + ' | '.join([l['id'], l['poste'], sg(l['v'][0], 2) + ' / **' + sg(l['v'][1], 2) + '** / ' + sg(l['v'][2], 2), l['cote']]) + ' |')
    rows.append('| | **Effet des nouvelles lignes** | ' + sg(EFFET_D8_NOUV[0], 2) + ' / **' + sg(EFFET_D8_NOUV[1], 2) + '** / ' + sg(EFFET_D8_NOUV[2], 2) + ' | |')
    return '\n'.join(rows)
def tests_d8():
    assert [l['id'] for l in L_D8] == ['GA01', 'GA02', 'TV06', 'TV07', 'TV08', 'TV09', 'TV10', 'CS01', 'CS02', 'PL01', 'PL02', 'OM01', 'OM02', 'CL01', 'JU01', 'EN01', 'ZA01', 'ZA02', 'IM01', 'VI01'], 'couche DECISIONS0811 : lignes'
    assert EFFET_D8_NOUV[0] >= EFFET_D8_NOUV[1] >= EFFET_D8_NOUV[2], 'couche 0811 : favorable >= central >= défavorable'
    proche(_D8['courbe']['r'][1]['net'], 9.0, 1e-6, 'courbe des pensions relevée : 9,00 Md€')
    proche(_D8['courbe']['o']['m'], _D7['courbe']['o']['m'] * 9.0 / _D7['courbe']['cible'], 1e-6, 'coefficient de la courbe = proportionnalité exacte (≈ 0,418)')
    proche(_D8['vieillesse']['reste'], _D8['vieillesse']['besoin'] - _D8['vieillesse']['hausseCourbe'], 1e-9, 'ligne vieillesse : reste = besoin − hausse de la courbe')
    proche(_D8['grandAge']['total'][1], 4.1, 1e-9, 'grand âge central 4,1 Md€ (3,2 + 0,9)')
    e = _D8['S3']
    proche(e['F'], e['revenus'] + e['credit'] + e['transmissions'] + e['patrimoineNat'] + e['pension'] + e['eco'], 1e-6, 'S3 0811 : F = somme des leviers')
    assert max(e['traj'][10:30]) <= e['traj'][9] + 1e-6 and e['picAn'] <= 2038, 'S3 0811 : dette stable à partir de 2038 (macro de référence)'
    proche(e['F'] - _D7['S3']['gtc_droite']['F'], -(e['effetCouche'] - _D7['S3']['gtc_droite']['effetCouche']) + _D8['r1f']['regime'], 0.3, 'S3 : F(0811) − F(0711) = −écart de couche + R1f perdue')
    assert e['cas']['smic_seul']['v'] > 0 and e['cas']['couple_2smic_2enf']['v'] > 0, 'S3 0811 : le Smic et le couple à deux Smic gagnent'
    assert all(r['v'] > 0 for r in e['retraites'] if r['pn'] <= 2000), 'S3 0811 : les retraités jusqu\'à 2 000 € ne perdent pas'
    assert _D8['clause']['pic']['retraites'] <= _D8['clause']['pensMax'] + 1e-9, 'clause : part des retraités plafonnée'
    return True

