def md_c8():
    rows = ['| Grandeur | Avant la correction (couche 0811) | **Après la correction** |', '|---|---|---|']
    rows.append('| Leviers S3 (Md€/an) | ' + fmt(_C8A['F'], 2) + ' | **' + fmt(_C8S['F'], 2) + '** |')
    rows.append('| Coefficient a de la fonction des revenus | ' + fmt(_C8A['a'], 4) + ' | **' + fmt(_C8S['a'], 4) + '** |')
    rows.append('| Dette 2038 / 2058 (référence, % du PIB) | ' + fmt(100 * _C8A['traj'][9], 1) + ' / ' + fmt(100 * _C8A['traj'][29], 1) + ' | **' + fmt(100 * _C8S['traj'][9], 1) + ' / ' + fmt(100 * _C8S['traj'][29], 1) + '** |')
    rows.append('| Déficit 2038 / 2058 (% du PIB) | ' + fmt(100 * _C8A['def'][9], 1) + ' / ' + fmt(100 * _C8A['def'][29], 1) + ' | **' + fmt(100 * _C8S['def'][9], 1) + ' / ' + fmt(100 * _C8S['def'][29], 1) + '** |')
    rows.append('| Prélèvements obligatoires (% du PIB) | ' + fmt(100 * _C8A['po']['pct'], 1) + ' | **' + fmt(100 * _C8S['po']['pct'], 1) + '** |')
    rows.append('| Saut du solde primaire 2040-2041 (Md€ de 2025) | ' + sg(_C8['saut']['avant']['md'], 1) + ' | **' + sg(_C8['saut']['apres']['md'], 1) + '** |')
    return '\n'.join(rows)
def tests_c8():
    h = _C8['herites']; t = _C8['tresorerie']
    proche(h['total'], 25.0, 0.05, 'reports hérités retirés : 13,5 + 11,5 = 25,0 Md€')
    proche(t['flux'], 12.4, 0.05, 'trésorerie du différé de la v7.4 : flux de 12,4 Md€'); proche(t['encours'], 149, 0.5, 'encours de 149 Md€')
    assert abs(_C8['saut']['apres']['md']) < 1 and _C8['saut']['avant']['md'] > 20, 'le saut de 2040-2041 (24 Md€) disparaît'
    assert _C8S['F'] < _C8A['F'] and _C8S['a'] < _C8A['a'], 'moins de leviers et a plus bas'
    proche(_C8A['F'], _D8['S3']['F'], 1e-9, 'reconstitution exacte de S3 de la couche 0811 sans la correction')
