def tests():
    # Bases « avant »
    proche(sum(l['cur'] for l in L if l['id'] in ('P01', 'P02', 'P03', 'P04', 'P05', 'P06', 'P07', 'P08', 'P09', 'P10')), 885.9, 0.05, 'prélèvements supprimés + IS : 885,9 (Insee)')
