    proche(11.426 + 2.935 + 2.468 + 1.538, 18.367, 1e-9, 'part de C10 déjà dans la base R (coût employeur) = 18,367')
    proche(V74['reco']['effet'], -(3.884 + 3.153 + 2.221), 1e-9, 'recommandations restantes : C08, C09, C11')
    assert all(abs(r[2] - (27.204 if 'seule part' not in r[0] else 8.837)) < 1e-9 for r in REGLAGE_C10), 'réglages indicatifs : recette visée 27,204 (8,837 pour la part hors de R)'
    proche(V74['corrige']['effet'], EFFET_CORR, 1e-9, 'la dette « corrigée » de export_bilan_v74.js utilise le même effet que le bilan')
    proche(V74['corrige']['solde2060'], SOLDE_V74_CORR, 1e-3, 'solde corrigé : bilan = export JS')
    proche(V74['reco']['effet'], EFFET_RECO, 1e-9, 'scénario « recommandations » : même effet dans le bilan et dans l\'export')
    proche(sum(c['d_po'] + c['d_hors'] for c in CORR_T65 if c['id'] in ('C02', 'C03')), 0.0, 1e-9, 'C02 et C03 déplacent des recettes hors prélèvements vers les prélèvements, sans changer les recettes (C10, ajoutée ensuite, retire 27,204 de prélèvements)')
    assert all(c['id'] not in [x[0] for x in A_ARBITRER_T65] for c in CORR_T65), 'une ligne à arbitrer n\'est jamais appliquée'
    # Base de travail du 06/11 (v7.5, arbitrages 48-50, fantômes) : couche datée, non adoptée
    tests_base()
    # Couche transmissions et crédit d'IS partiel du 06/11 (arbitrage 53) : non adoptée
    tests_trans()
    tests_ecofonc()
    tests_ra()
    tests_conso()
    tests_gt()
    tests_d7()
    tests_d8()
    tests_c8()
    # Identité comptable
    proche(SOLDE_APRES, DEFICIT_AVANT + T['d_po'] - T['d_dep'], 1e-9, 'identité : solde = déficit + Δ prélèvements − Δ dépenses')
    for l in L:
        assert l['sens'] in ('rec', 'dep')
        if l['cur']: assert cible(l) > -1e-9, 'cible négative pour un poste existant : ' + l['id']
        if 'supprimé → 0' in l['statut'] and l['cur'] is not None: proche(cible(l), 0.0, 1e-9, 'supprimé = cible nulle : ' + l['id'])
    # Les restes sont positifs
    for fn, r in T['restes'].items(): assert r > -1e-9, 'reste négatif pour ' + fn
    return True

